var n=[{title:`Spécificité et surcharge`,text:`La spécificité signifie que votre corps s’adapte à ce que vous pratiquez : soulever améliore la force de levée, et pédaler développe l’endurance à vélo. La surcharge signifie que le défi doit être assez grand pour provoquer une adaptation. Vous n’avez pas besoin d’un poids plus lourd à chaque séance. Une répétition contrôlée de plus ou une exécution plus propre compte aussi comme progrès.`},{title:`Individualisation et progression`,text:`Les gens réagissent différemment selon l’expérience, la capacité, l’emploi du temps, l’environnement et les objectifs. Un débutant peut s’améliorer avec deux courtes séances par semaine, tandis qu’un pratiquant expérimenté peut avoir besoin d’un entraînement réparti plus soigneusement. La progression consiste à rendre les choses plus difficiles une fois que vous avez montré que vous êtes prêt. Aller vite n’est pas le but.`},{title:`Récupération, régularité et réversibilité`,text:`Vous vous adaptez grâce à l’entraînement répété et à la récupération entre les séances. Le sommeil, l’alimentation et un emploi du temps que vous pouvez tenir déterminent si vous pouvez continuer. La réversibilité signifie que certains bénéfices s’estompent quand vous arrêtez de vous entraîner, à un rythme qui dépend de vous et de la capacité concernée. Manquer une séance n’efface pas vos progrès.`},{title:`Varier avec une raison`,text:`Changer un exercice peut éviter l’ennui ou contourner du matériel manquant, mais si vous remplacez chaque mouvement chaque semaine, vous ne pouvez pas savoir si vous progressez. Gardez vos schémas principaux identiques pendant plusieurs semaines et changez les exercices complémentaires ou les charges quand vous avez une raison. La prise de position 2026 de l’ACSM indique que de nombreux programmes différents fonctionnent tant que vous continuez à vous entraîner et à pousser votre effort vers l’avant.`},{title:`Avec TrainUp`,text:`Votre objectif se trouve dans Profil, chaque séance enregistre les séries et répétitions que vous terminez, et vous évaluez ensuite l’effort de la séance (RPE). Quand vous régénérez votre programme, il change d’un cran à la fois d’après ce suivi, afin qu’un programme générique ne reste pas figé pour vous. Si vous ajustez les choses vous-même, changez une ou deux variables à la fois.`}];var t=[{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Conseils de l’ACSM sur le modèle de progression`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`},{label:`NSCA : sécurité et fondamentaux du renforcement`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var i={sections:n,sources:t};export{i as default,n as sections,t as sources};